const consoleUrls = new Set([
  'console.dev.devim.io',
  'console.staging.devim.io',
  'console.demo.devim.io',
  'console.vim.com',
]);

export const useNavigationLink = (appId: string) => {
  let hostName = window.location.hostname;

  if (!consoleUrls.has(hostName)) {
    hostName = 'console.getvim.com'; // default to prod
  }

  return `https://${hostName}/organization-admin/public-page/app-store/${appId}`;
};
