import React from 'react';

export interface PermissionItemProps {
  label: string;
  value: string;
  labelClassName?: string;
  valueClassName?: string;
}

export const PermissionItem: React.FC<PermissionItemProps> = ({
  label,
  value,
  labelClassName = 'text-sm font-semibold leading-[1.5]',
  valueClassName = 'text-sm text-gray-600 leading-[1.5]',
}) => {
  return (
    <div>
      <span className={labelClassName}>{label}: </span>
      <span className={valueClassName}>{value}</span>
    </div>
  );
};

interface EhrWritePermissionsProps {
  writePermissions?: {
    encounterWritePermissionTags?: string;
    referralWritePermissionTags?: string;
    ordersWritePermissionTags?: string;
  };
  labelClassName?: string;
  valueClassName?: string;
}

export const EhrWritePermissions: React.FC<EhrWritePermissionsProps> = ({
  writePermissions,
  labelClassName,
  valueClassName,
}) => {
  if (!writePermissions) {
    return null;
  }

  const { encounterWritePermissionTags, referralWritePermissionTags, ordersWritePermissionTags } =
    writePermissions;

  return (
    <>
      {encounterWritePermissionTags && (
        <PermissionItem
          label="Encounter"
          value={encounterWritePermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {referralWritePermissionTags && (
        <PermissionItem
          label="Referral"
          value={referralWritePermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {ordersWritePermissionTags && (
        <PermissionItem
          label="Orders"
          value={ordersWritePermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
    </>
  );
};
