import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import styled from 'styled-components';
import { MultiSelectItem } from '../../types';

interface MultiSelectProps {
  label: string;
  maxDisplay: number;
  allOptions: MultiSelectItem[];
  selectedOptions: MultiSelectItem[];
  onChange: (selectedOptions: MultiSelectItem[]) => void;
}

const MultiSelectDropdown: React.FC<MultiSelectProps> = ({
  label,
  maxDisplay,
  allOptions,
  selectedOptions,
  onChange,
}) => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const dropdownRef = useRef<HTMLDivElement>(null);

  const menuOptions = useMemo(() => {
    const selectedIds = new Set(selectedOptions.map((option) => option.id));
    const optionsToShow = allOptions.map((option) => ({
      ...option,
      checked: selectedIds.has(option.id),
    }));

    if (!searchTerm.trim()) {
      return optionsToShow;
    }

    return optionsToShow.filter((option) =>
      String(option.value).toLowerCase().includes(searchTerm.toLowerCase()),
    );
  }, [allOptions, searchTerm, selectedOptions]);

  const hiddenOptionsCount = useMemo(() => {
    const selectedCount = selectedOptions.length;
    return selectedCount - maxDisplay;
  }, [maxDisplay, selectedOptions.length]);

  const toggleDropdown = useCallback(() => {
    setIsDropdownOpen(!isDropdownOpen);
  }, [isDropdownOpen]);

  const handleSearch = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  }, []);

  const handleChange = useCallback(
    (option: MultiSelectItem) => {
      const shouldRemove = selectedOptions.some((selected) => selected.id === option.id);

      const updatedOptions = shouldRemove
        ? selectedOptions.filter((selected) => selected.id !== option.id)
        : [...selectedOptions, option];

      onChange(updatedOptions);
    },
    [selectedOptions, onChange],
  );

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Reset search term when dropdown closes
  useEffect(() => {
    if (!isDropdownOpen) {
      setSearchTerm('');
    }
  }, [isDropdownOpen]);

  const displayedOptions = selectedOptions.slice(0, maxDisplay);

  if (allOptions.length === 0) {
    return null;
  }

  return (
    <Wrapper>
      <Label>{label}: </Label>
      <SelectionContainer>
        {allOptions.length > selectedOptions.length && (
          <AddButton onClick={toggleDropdown}>+ Add</AddButton>
        )}

        {displayedOptions.map((option) => (
          <Tag key={option.id}>
            {option.value}
            <RemoveButton
              data-testid={`remove-option-${option.id}`}
              // eslint-disable-next-line react/jsx-no-bind
              onClick={() => handleChange(option)}
            >
              ×
            </RemoveButton>
          </Tag>
        ))}

        <MoreOptionsContainer>
          {hiddenOptionsCount > 0 && selectedOptions.length > 0 ? (
            <MoreButton onClick={toggleDropdown}>{`+${hiddenOptionsCount} `}</MoreButton>
          ) : null}
        </MoreOptionsContainer>

        {isDropdownOpen && (
          <DropdownContainer>
            <Dropdown ref={dropdownRef}>
              <DropdownHeader>Select Options</DropdownHeader>
              <SearchContainer>
                <SearchInput placeholder="Search" onChange={handleSearch} autoFocus />
                <SearchIcon>🔍</SearchIcon>
              </SearchContainer>
              <OptionsList>
                {menuOptions.map((option) => (
                  <OptionItem
                    key={option.id}
                    // eslint-disable-next-line react/jsx-no-bind
                    onClick={() => handleChange(option)}
                  >
                    <Checkbox checked={option.checked} readOnly />
                    <OptionLabel>{option.value}</OptionLabel>
                  </OptionItem>
                ))}
              </OptionsList>
            </Dropdown>
          </DropdownContainer>
        )}
      </SelectionContainer>
    </Wrapper>
  );
};

// Styled components with generic names
const Wrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  position: relative;
`;

const Label = styled.span`
  font-size: 14px;
  margin-right: 8px;
  font-weight: bold;
`;

const SelectionContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  position: relative;
`;

const Tag = styled.span`
  border-radius: 12px;
  padding: 0px 10px;
  font-size: 13px;
  margin-right: 8px;
  display: inline-flex;
  align-items: center;
  border: 1.5px solid #001c36;
`;

const RemoveButton = styled.button`
  background: none;
  border: none;
  color: #666;
  font-size: 14px;
  margin-left: 4px;
  cursor: pointer;
  padding: 0 2px;
  &:hover {
    color: #333;
  }
`;

const MoreOptionsContainer = styled.div`
  display: inline-block;
`;

const BaseButton = styled.button`
  font-size: 14px;
  cursor: pointer;
  text-decoration: underline;
  font-weight: bold;
  color: ${(props) => props.color};
  background: none;
  border: none;
`;

const MoreButton = styled(BaseButton)`
  color: black;
`;

const AddButton = styled(BaseButton)`
  color: #10abe4;
  margin-right: 4px;
  font-weight: normal;
`;

const DropdownContainer = styled.div`
  position: absolute;
  top: 100%;
  left: 0;
  margin-top: 8px;
  z-index: 1000;
`;

const Dropdown = styled.div`
  width: 250px;
  background-color: white;
  border: 1px solid #ddd;
  border-radius: 4px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const DropdownHeader = styled.div`
  padding: 10px 15px;
  font-weight: 500;
  border-bottom: 1px solid #eee;
`;

const SearchContainer = styled.div`
  position: relative;
  padding: 10px 15px;
  border-bottom: 1px solid #eee;
`;

const SearchInput = styled.input`
  width: 100%;
  padding: 8px;
  padding-right: 30px;
  border: 1px solid #ddd;
  border-radius: 4px;
  font-size: 14px;
`;

const SearchIcon = styled.span`
  position: absolute;
  right: 25px;
  top: 50%;
  transform: translateY(-50%);
  color: #999;
`;

const OptionsList = styled.div`
  max-height: 200px;
  overflow-y: auto;
`;

const OptionItem = styled.div`
  display: flex;
  align-items: center;
  padding: 10px 15px;
  cursor: pointer;
  &:hover {
    background-color: #f5f5f5;
  }
`;

const Checkbox = styled.input.attrs({ type: 'checkbox' })`
  margin-right: 10px;
`;

const OptionLabel = styled.span`
  font-size: 14px;
`;

export default MultiSelectDropdown;
