import React from 'react';
import type { AppStoreServiceManifest } from '@getvim-os/types';
import { PermissionItem } from './EhrWritePermissions';

interface EhrReadPermissionsProps {
  readPermissions?: {
    hasContactInfoReadPermission?: boolean;
    patientPermissionTags?: string;
    encounterPermissionTags?: string;
    referralPermissionTags?: string;
    ordersPermissionTags?: string;
    claimPermissionTags?: string;
    appointmentsPermissions?: AppStoreServiceManifest;
  };
  labelClassName?: string;
  valueClassName?: string;
}

export const EhrReadPermissions: React.FC<EhrReadPermissionsProps> = ({
  readPermissions,
  labelClassName,
  valueClassName,
}) => {
  if (!readPermissions) {
    return null;
  }

  const {
    hasContactInfoReadPermission,
    patientPermissionTags,
    encounterPermissionTags,
    referralPermissionTags,
    ordersPermissionTags,
    claimPermissionTags,
    appointmentsPermissions,
  } = readPermissions;

  return (
    <>
      {hasContactInfoReadPermission && (
        <span className={labelClassName || 'text-sm font-semibold leading-[1.5]'}>
          Vim Connect user profile data
        </span>
      )}
      {patientPermissionTags && (
        <PermissionItem
          label="EHR patient information"
          value={patientPermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {encounterPermissionTags && (
        <PermissionItem
          label="EHR encounter information"
          value={encounterPermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {referralPermissionTags && (
        <PermissionItem
          label="EHR referral information"
          value={referralPermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {ordersPermissionTags && (
        <PermissionItem
          label="EHR orders information"
          value={ordersPermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {claimPermissionTags && (
        <PermissionItem
          label="EHR claim information"
          value={claimPermissionTags}
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
      {appointmentsPermissions && (
        <PermissionItem
          label="EHR appointments information"
          value="Ongoing bulk access to future appointments. For this permission, you authorize Vim to use any live EHR user session to retrieve appointment data for your EHR on an ongoing basis."
          labelClassName={labelClassName}
          valueClassName={valueClassName}
        />
      )}
    </>
  );
};
